package com.hiresense.service;
import com.hiresense.domain.*; import com.hiresense.domain.enums.RoleName; import com.hiresense.dto.AuthDtos.*; import com.hiresense.exception.ApiException; import com.hiresense.repository.*; import com.hiresense.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.authentication.*; import org.springframework.security.core.AuthenticationException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.stream.Collectors;
@Service public class AuthService { private final AppUserRepository users; private final RoleRepository roles; private final CandidateProfileRepository profiles; private final PasswordEncoder encoder; private final AuthenticationManager auth; private final JwtService jwt;
 public AuthService(AppUserRepository u,RoleRepository r,CandidateProfileRepository p,PasswordEncoder e,AuthenticationManager a,JwtService j){users=u;roles=r;profiles=p;encoder=e;auth=a;jwt=j;}
 @Transactional public AuthResponse register(RegisterRequest req){if(users.existsByEmailIgnoreCase(req.email()))throw new ApiException(HttpStatus.CONFLICT,"Email already registered");Role role=roles.findByName(RoleName.CANDIDATE).orElseThrow(()->ApiException.bad("Candidate role is not seeded"));AppUser u=new AppUser();u.setFullName(req.fullName().trim());u.setEmail(req.email().trim().toLowerCase(Locale.ROOT));u.setPasswordHash(encoder.encode(req.password()));u.setActive(true);u.setRoles(new HashSet<>(Set.of(role)));u=users.save(u);CandidateProfile p=new CandidateProfile();p.setUser(u);profiles.save(p);return response(u);}
 public AuthResponse login(LoginRequest req){try{auth.authenticate(new UsernamePasswordAuthenticationToken(req.email(),req.password()));}catch(AuthenticationException e){throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid credentials");}AppUser u=users.findByEmailIgnoreCase(req.email()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));return response(u);}
 private AuthResponse response(AppUser u){Set<String> rs=u.getRoles().stream().map(r->r.getName().name()).collect(Collectors.toSet());return new AuthResponse(jwt.generate(u.getEmail(),rs),jwt.expiration(),new UserResponse(u.getId(),u.getFullName(),u.getEmail(),u.isActive(),rs));}
}
